// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 minSum, uint256 lockTime, uint256 putValue, uint256 collectAmount, uint256 timeSkip) public {
        // Bound and constrain parameters
        vm.assume(minSum > 0);
        vm.assume(putValue < type(uint256).max / 2);
        vm.assume(collectAmount <= putValue);
        vm.assume(timeSkip > 0 && timeSkip < type(uint256).max / 2);

        // Set up state: deploys with intitalized=false, set MinSum
        c.SetMinSum(minSum);
        uint256 expectedMinSum = minSum;

        // Put some ether in the contract via a user
        address user = address(0x1234);
        vm.deal(user, putValue);
        vm.prank(user);
        c.Put{value: putValue}(lockTime);

        // Warp time past unlock
        vm.warp(block.timestamp + timeSkip + lockTime + 1);

        // Call Collect - this may revert if insufficient balance etc, but we just observe state after call
        // We'll use try/catch to handle possible revert
        bool reverts;
        try c.Collect(collectAmount) {
            reverts = false;
        } catch {
            reverts = true;
        }

        // General rule: MinSum should remain unchanged (equal to expectedMinSum) regardless of whether Collect reverted
        assertTrue(c.MinSum() == expectedMinSum, "MinSum changed after Collect call");
    }
}

