pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _val, uint256 _lockTime, uint256 _am, uint256 _deposit) public {
        vm.assume(_val <= type(uint256).max);
        vm.assume(_lockTime <= type(uint256).max);
        vm.assume(_am <= type(uint256).max);
        vm.assume(_deposit <= type(uint256).max);

        // Attempt to set MinSum first
        c.SetMinSum(_val);

        // Now deposit some ether to create a balance
        vm.deal(address(this), _deposit);
        c.Put{value: _deposit}(_lockTime);

        // Get MinSum before Collect
        uint256 minSumBefore = c.MinSum();

        // Call Collect
        (bool successCollect, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, _am));

        // After Collect, MinSum should stay the same as before because the only way to change it
        // is via SetMinSum when intitalized is false. Since we didn't call Initialized,
        // intitalized remains false, so SetMinSum works. But in the buggy version, SetMinSum
        // requires intitalized to be true (which it never is), so the first SetMinSum call
        // reverts and MinSum stays at its default 0. After Collect, MinSum should remain unchanged.
        assertTrue(c.MinSum() == minSumBefore, "MinSum changed after Collect");
    }
}

