// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _val1, uint256 _val2, uint256 _lockTime, uint256 _am) public {
        // Bound inputs to realistic ranges
        _val1 = bound(_val1, 0, 1e30);
        _val2 = bound(_val2, 0, 1e30);
        _lockTime = bound(_lockTime, 0, 1e6);
        _am = bound(_am, 0, 1e30);

        // If initialized is false, set MinSum; if true, both calls revert, MinSum unchanged
        bool initializedBefore = false;
        try c.Initialized() {
            initializedBefore = true;
        } catch {}

        // Record MinSum before potential SetMinSum
        uint256 minSumBefore = c.MinSum();

        // Call SetMinSum if initialized is false (it will succeed)
        if (!initializedBefore) {
            c.SetMinSum(_val1);
        }

        // Now call Collect (may or may not revert)
        try c.Collect(_am) {
            // Collect succeeded, MinSum should be unchanged from last successful SetMinSum
            assertTrue(c.MinSum() == minSumBefore || c.MinSum() == _val1);
        } catch {
            // Collect reverted, MinSum unchanged
            assertTrue(c.MinSum() == minSumBefore || c.MinSum() == _val1);
        }

        // Also test a second sequence to catch bug where SetMinSum writes even when initialized
        bool initializedAfter = false;
        try c.Initialized() {
            initializedAfter = true;
        } catch {}
        if (!initializedAfter) {
            c.SetMinSum(_val2);
            minSumBefore = c.MinSum();
        }
        try c.Collect(_am) {
            assertTrue(c.MinSum() == minSumBefore);
        } catch {
            assertTrue(c.MinSum() == minSumBefore);
        }
    }
}

