pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 initVal, uint256 setVal, uint256 lockTime, uint256 collectAmt) public {
        // Bound inputs to realistic ranges
        initVal = bound(initVal, 0, 1e18);
        setVal = bound(setVal, 1, 1e18);
        lockTime = bound(lockTime, 0, 1000000);
        collectAmt = bound(collectAmt, 0, 1e18);

        // Start with a known state: set MinSum to initVal before initialization
        c.SetMinSum(initVal);
        uint256 setMinSumBefore = c.MinSum();

        // Now initialize the contract, so SetMinSum can no longer be called
        c.Initialized();

        // Try to change MinSum after initialization (this should revert in reference C)
        // but we do it to test the invariant after Collect
        // Use vm.expectRevert to catch if it reverts (reference behavior)
        vm.expectRevert();
        c.SetMinSum(setVal);

        // Now call Collect with some amount and lockTime
        // First we need some balance for the caller
        address payable caller = payable(address(0x1234));
        vm.deal(caller, 1e18);
        vm.prank(caller);
        c.Put{value: 1e18}(lockTime);

        // Warp time to make unlockTime pass
        vm.warp(block.timestamp + lockTime + 1);

        vm.prank(caller);
        c.Collect(collectAmt);

        // After Collect, MinSum should be <= the last set value (which was initVal)
        // In reference C, initialized prevents SetMinSum from changing MinSum, so MinSum stays as initVal
        // In mutant, SetMinSum sets MinSum to 0 when initialized is true, so MinSum becomes 0
        uint256 minSumAfter = c.MinSum();
        assertTrue(minSumAfter <= initVal, "MinSum should not increase after Collect");
    }
}

