// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 minSum, uint256 lockTime, uint256 deposit, uint256 collectAmount) public {
        // Restrict inputs: deposit at least enough to fund collect, avoid overflow
        vm.assume(deposit < type(uint256).max / 2);
        vm.assume(lockTime < type(uint256).max / 2);
        vm.assume(collectAmount <= deposit);
        vm.assume(minSum <= deposit); // ensure MinSum <= balance for collect to succeed

        // Step 1: SetMinSum before initialization
        c.SetMinSum(minSum);

        // Step 2: Record the MinSum value just set
        uint256 expectedMinSum = minSum;

        // Step 3: Initialize the contract (irreversible)
        c.Initialized();

        // Step 4: Put some ETH into the contract (locked for future)
        vm.deal(address(this), deposit);
        c.Put{value: deposit}(lockTime);

        // Step 5: Warp time past the unlock time
        vm.warp(block.timestamp + lockTime + 1);

        // Step 6: Collect
        (bool success,) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // The rule: Before calling SetMinSum after initialization, MinSum must equal the last value set before init
        // Since we never called SetMinSum after init, MinSum should remain unchanged
        if (success) {
            assertTrue(c.MinSum() == expectedMinSum, "MinSum should equal the value set before initialization");
        } else {
            // If Collect reverts (e.g., due to insufficient balance), the state is unchanged
            assertTrue(c.MinSum() == expectedMinSum, "Even on revert, MinSum should be unchanged");
        }
    }
}

