        vm.deal(address(this), depositAm);
        c.Put{value: depositAm}(lockTime);

        // Record MinSum before Collect
        uint256 minSumBefore = c.MinSum();

        // Step 3: Execute Collect (it may revert or succeed, but we only care about MinSum after)
        // Use try/catch to handle revert
        bool collectReverted;
        try c.Collect(collectAm) {
            collectReverted = false;
        } catch {
