        (bool putSuccess, ) = address(c).call{value: 1 ether}(abi.encodeWithSignature("Put(uint256)", 0));
        if (!putSuccess) return; // Skip if Put fails

        // Try Collect with large amount to fail
        vm.prank(caller);
        (bool colSuccess, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", amount));

        // Now try to call Initialized() - in reference it should succeed (lock released)
        // but in buggy version it might revert or succeed
        vm.prank(caller);
        (bool initSuccess, ) = address(c).call(abi.encodeWithSignature("Initialized()"));

        // The rule: Initialized() should succeed (i.e., not revert) after a failed Collect
        assertTrue(initSuccess);
    }
}

